const cfg=window.VASE_VOW_CONFIG;const pageDialog=document.querySelector('#page-dialog');let lastFocus;
function openDialog(d){lastFocus=document.activeElement;d.showModal();d.querySelector('.close').focus()}
document.querySelectorAll('.page-preview').forEach(b=>b.addEventListener('click',()=>{const im=document.querySelector('#page-image');im.src=b.dataset.page;im.alt=b.dataset.label;document.querySelector('#page-title').textContent=b.dataset.label;openDialog(pageDialog)}));
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>lastFocus?.focus())});
document.querySelector('[data-terms]').addEventListener('click',()=>openDialog(document.querySelector('#terms-dialog')));
document.querySelectorAll('[data-review-order]').forEach(link=>link.addEventListener('click',()=>{const u=new URL('purchase.html',location.href);for(const k of ['utm_source','utm_medium','utm_campaign','utm_content']){const v=new URLSearchParams(location.search).get(k);if(v)u.searchParams.set(k,v.slice(0,100))}link.href=u.href}));
const sticky=document.querySelector('.sticky');let heroVisible=true,offerVisible=false;function updateSticky(){sticky.hidden=heroVisible||offerVisible||matchMedia('(min-width:761px)').matches}new IntersectionObserver(es=>{heroVisible=es[0].isIntersecting;updateSticky()},{threshold:0}).observe(document.querySelector('.hero .actions'));new IntersectionObserver(es=>{offerVisible=es[0].isIntersecting;updateSticky()},{threshold:.15}).observe(document.querySelector('#offer'));window.addEventListener('resize',updateSticky);
const tableCount=document.querySelector('#table-count');const flowerChoice=document.querySelector('#flower-choice');const result=document.querySelector('.quantity-result');
function calculatePlan(tables,plan){const vases=tables*4;const stems=vases*2;return {vases,stems,breakdown:plan==='mix'?`${vases} white carnation + ${vases} pink alstroemeria stems`:`${stems} ${plan==='pink'?'pink alstroemeria':'white carnation'} stems`}}
function updatePlan(){const n=calculatePlan(Number(tableCount.value),flowerChoice.value);document.querySelector('#vase-count').textContent=n.vases;document.querySelector('#stem-count').textContent=n.stems;document.querySelector('#stem-breakdown').textContent=n.breakdown;result.classList.remove('updated');requestAnimationFrame(()=>result.classList.add('updated'))}
tableCount.addEventListener('change',updatePlan);flowerChoice.addEventListener('change',updatePlan);
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');if(!motionPreference.matches&&'IntersectionObserver' in window){const reveal=new IntersectionObserver(es=>{for(const e of es){if(e.isIntersecting){e.target.classList.add('motion-enter');reveal.unobserve(e.target)}}},{threshold:.08});document.querySelectorAll('.section-head,.quantity-copy,.quantity-card,.inside-copy,.book-display,.method li,.offer-card,.closing h2').forEach(el=>reveal.observe(el))}
const progress=document.querySelector('.reading-progress span');let scrollQueued=false;function paintProgress(){const max=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${max>0?Math.min(1,Math.max(0,scrollY/max)):0})`;scrollQueued=false}window.addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(paintProgress)}},{passive:true});window.addEventListener('resize',paintProgress);paintProgress();
